function lesson(
  title: string,
  intro: string,
  rule: string,
  wrongOne: string,
  wrongTwo: string,
  calculationPrompt: string,
  answer: number,
  steps: [string, string, string],
  insight: string,
  hint: string,
): LessonSeed {
  return {
    title,
    intro,
    rule,
    distractors: [wrongOne, wrongTwo],
    calculationPrompt,
    answer,
    steps,
    insight,
    hint,
  };
}

