function normalizeSkillKey(name: string): string {
  return name.trim().toLowerCase().replace(/\s+/g, '-');
}

function rotate<T>(items: T[], offset: number): T[] {
  const index = offset % items.length;
  return items.slice(index).concat(items.slice(0, index));
}

export function buildQuestPuzzles(quest: QuestSeed): SeedPuzzle[] {
  return quest.levels.flatMap((level, levelIndex) => {
    const baseOrder = levelIndex * 3;
    const optionLabels = [level.rule, ...level.distractors];
    const correctPosition = (questSeeds.indexOf(quest) + levelIndex) % optionLabels.length;
    const rotatedOptions = rotate(optionLabels, correctPosition);
    const correctOptionId = 'option_' + rotatedOptions.indexOf(level.rule);
    const choiceOptions = rotatedOptions.map((label, index) => ({
      id: 'option_' + index,
      label,
    }));
    const correctSteps = level.steps.map((_, index) => 'step_' + index);
    const displayedSteps = rotate([...level.steps].reverse(), (questSeeds.indexOf(quest) + levelIndex) % 3);
    const itemIdByLabel = new Map(level.steps.map((step, index) => [step, 'step_' + index]));
    return [
      {
        orderNo: baseOrder + 1,
        type: 'single_choice' as const,
        publicPayload: {
          prompt: 'Ситуация: ' + level.intro + ' Какое правило лучше всего объясняет происходящее?',
          options: choiceOptions,
        },
        solutionPrivate: {
          correctOptionId,
          correctFeedback: level.insight,
          incorrectFeedback: level.hint,
        },
        hint: level.hint,
      },
      {
        orderNo: baseOrder + 2,
        type: 'numeric_input' as const,
        publicPayload: {
          prompt: level.calculationPrompt,
          placeholder: 'Введи число',
        },
        solutionPrivate: {
          correctValue: level.answer,
          tolerance: 0,
          correctFeedback: level.insight,
          incorrectFeedback: level.hint,
        },
        hint: level.hint,
      },
      {
        orderNo: baseOrder + 3,
        type: 'ordering' as const,
        publicPayload: {
          prompt: 'Расположи этапы решения в правильном порядке.',
          items: displayedSteps.map((step) => ({
            id: itemIdByLabel.get(step) as string,
            label: step,
          })),
        },
        solutionPrivate: {
          correctOrderIds: correctSteps,
          correctFeedback: level.insight,
          incorrectFeedback: level.hint,
        },
        hint: level.hint,
      },
    ];
  });
}

export function validateSeedLibrary(): string[] {
  const errors: string[] = [];
  const categorySlugs = new Set(categorySeeds.map((category) => category.slug));
  const skillNames = new Set(skillSeeds.map((skill) => skill.name));
  const questSlugs = new Set<string>();
  const skillUsage = new Map(skillSeeds.map((skill) => [skill.name, 0]));

  for (const skill of skillSeeds) {
    for (const prerequisite of skill.prerequisites) {
      if (!skillNames.has(prerequisite)) errors.push('Unknown prerequisite "' + prerequisite + '" for "' + skill.name + '".');
    }
  }

  const visiting = new Set<string>();
  const visited = new Set<string>();
  const skillByName = new Map(skillSeeds.map((skill) => [skill.name, skill]));
  const visitSkill = (name: string): void => {
    if (visiting.has(name)) {
      errors.push('Prerequisite cycle detected at "' + name + '".');
      return;
    }
    if (visited.has(name)) return;
    visiting.add(name);
    for (const prerequisite of skillByName.get(name)?.prerequisites ?? []) {
      if (skillByName.has(prerequisite)) visitSkill(prerequisite);
    }
    visiting.delete(name);
    visited.add(name);
  };
  for (const skill of skillSeeds) visitSkill(skill.name);

  for (const quest of questSeeds) {
    if (questSlugs.has(quest.slug)) errors.push('Duplicate quest slug "' + quest.slug + '".');
    questSlugs.add(quest.slug);
    if (!categorySlugs.has(quest.category)) errors.push('Unknown category "' + quest.category + '" in "' + quest.slug + '".');
    if (quest.levels.length < 3) errors.push('Quest "' + quest.slug + '" must have at least three levels.');
    for (const skillName of quest.skills) {
      if (!skillNames.has(skillName)) {
        errors.push('Unknown skill "' + skillName + '" in "' + quest.slug + '".');
        continue;
      }
      skillUsage.set(skillName, (skillUsage.get(skillName) ?? 0) + 1);
      if (!quest.objectives.some((objective) => objective.includes(skillName))) {
        errors.push('Quest "' + quest.slug + '" does not link skill "' + skillName + '" to an objective.');
      }
    }
    const puzzles = buildQuestPuzzles(quest);
    const taskTypes = new Set(puzzles.map((puzzle) => puzzle.type));
    if (puzzles.length < 3) errors.push('Quest "' + quest.slug + '" has fewer than three puzzles.');
    if (taskTypes.size < 2) errors.push('Quest "' + quest.slug + '" has fewer than two task types.');
    for (const puzzle of puzzles) {
      if (puzzle.type === 'single_choice') {
        const options = puzzle.publicPayload.options as Array<{ id: string; label: string }>;
        const answer = puzzle.solutionPrivate.correctOptionId;
        if (!options.some((option) => option.id === answer)) errors.push('Invalid single-choice answer in "' + quest.slug + '".');
      }
      if (puzzle.type === 'ordering') {
        const items = puzzle.publicPayload.items as Array<{ id: string; label: string }>;
        const answer = puzzle.solutionPrivate.correctOrderIds as string[];
        if (items.length !== answer.length || answer.some((id) => !items.some((item) => item.id === id))) {
          errors.push('Invalid ordering answer in "' + quest.slug + '".');
        }
      }
    }
  }

  for (const [skillName, uses] of skillUsage) {
    if (uses < 3) errors.push('Skill "' + skillName + '" is used by only ' + uses + ' quests; at least three are required.');
  }
  if (questSeeds.length < 20 || questSeeds.length > 30) {
    errors.push('The initial library must contain between 20 and 30 quests.');
  }

  return errors;
}

export async function seedLearningLibrary(client: PoolClient): Promise<void> {
  const diagnostics = validateSeedLibrary();
  if (diagnostics.length > 0) {
    throw new Error('Seed content validation failed:\n- ' + diagnostics.join('\n- '));
  }

  const categoryIds = new Map<string, string>();
  for (const category of categorySeeds) {
    const result = await client.query<{ id: string }>(
      `INSERT INTO categories
       (id, slug, locale, title, description, status, sort_order, updated_at)
       VALUES ($1, $2, 'ru', $3, $4, 'PUBLISHED', $5, NOW())
       ON CONFLICT (locale, slug) DO UPDATE SET
         title = EXCLUDED.title,
         description = EXCLUDED.description,
         status = 'PUBLISHED',
         sort_order = EXCLUDED.sort_order,
         updated_at = NOW()
       RETURNING id`,
      [randomUUID(), category.slug, category.title, category.description, categorySeeds.indexOf(category) + 1],
    );
    categoryIds.set(category.slug, result.rows[0].id);
  }

  const skillIds = new Map<string, string>();
  for (const skill of skillSeeds) {
    const result = await client.query<{ id: string }>(
      `INSERT INTO skills (id, key, name, description, difficulty)
       VALUES ($1, $2, $3, $4, $5)
       ON CONFLICT (key) DO UPDATE SET
         description = COALESCE(skills.description, EXCLUDED.description),
         difficulty = COALESCE(skills.difficulty, EXCLUDED.difficulty)
       RETURNING id`,
      [randomUUID(), normalizeSkillKey(skill.name), skill.name, skill.description, skill.difficulty],
    );
    skillIds.set(skill.name, result.rows[0].id);
  }

  for (const skill of skillSeeds) {
    for (const prerequisiteName of skill.prerequisites) {
      const skillId = skillIds.get(skill.name);
      const prerequisiteId = skillIds.get(prerequisiteName);
      if (!skillId || !prerequisiteId) {
        throw new Error('Skill prerequisite could not be resolved for "' + skill.name + '".');
      }
      await client.query(
        `INSERT INTO skill_prerequisites (skill_id, prerequisite_id)
         VALUES ($1, $2)
         ON CONFLICT (skill_id, prerequisite_id) DO NOTHING`,
        [skillId, prerequisiteId],
      );
    }
  }

  for (const quest of questSeeds) {
    const categoryId = categoryIds.get(quest.category);
    if (!categoryId) throw new Error('Category "' + quest.category + '" not found for "' + quest.slug + '".');
    const questResult = await client.query<{ id: string }>(
      `INSERT INTO quests (id, category_id, slug, status, updated_at)
       VALUES ($1, $2, $3, 'DRAFT', NOW())
       ON CONFLICT (slug) DO UPDATE SET category_id = EXCLUDED.category_id, updated_at = NOW()
       RETURNING id`,
      [randomUUID(), categoryId, quest.slug],
    );
    const questId = questResult.rows[0].id;
    const skillTags = quest.skills;
    const objectivesJson = JSON.stringify(quest.objectives);
    const seoJson = JSON.stringify({ title: quest.title, description: quest.seoDescription });
    let versionId: string;
    const insertedVersion = await client.query<{ id: string }>(
      `INSERT INTO quest_versions
       (id, quest_id, version_no, title, summary, objectives, age_min, age_max,
        difficulty, duration_min, locale, seo, status, published_at,
        internal_name, description, skills)
       VALUES ($1, $2, 1, $3, $4, $5::jsonb, $6, $7, $8, $9, 'ru',
        $10::jsonb, 'PUBLISHED', NOW(), $11, $12, $13)
       ON CONFLICT (quest_id, version_no) DO NOTHING
       RETURNING id`,
      [
        randomUUID(), questId, quest.title, quest.summary, objectivesJson,
        quest.ageMin, quest.ageMax, quest.difficulty, quest.durationMin,
        seoJson, quest.internalName, quest.description, skillTags,
      ],
    );

    if (insertedVersion.rows[0]) {
      versionId = insertedVersion.rows[0].id;
    } else {
      const existingVersion = await client.query<{ id: string; status: string }>(
        'SELECT id, status FROM quest_versions WHERE quest_id = $1 AND version_no = 1',
        [questId],
      );
      const existing = existingVersion.rows[0];
      if (!existing) throw new Error('Quest version could not be found for "' + quest.slug + '".');
      if (existing.status === 'PUBLISHED') {
        continue;
      }
      if (existing.status !== 'DRAFT') {
        throw new Error('Refusing to overwrite editorial state "' + existing.status + '" for "' + quest.slug + '".');
      }
      versionId = existing.id;
      await client.query(
        `UPDATE quest_versions SET
           title = $2, summary = $3, objectives = $4::jsonb, age_min = $5, age_max = $6,
           difficulty = $7, duration_min = $8, seo = $9::jsonb, internal_name = $10,
           description = $11, skills = $12
         WHERE id = $1 AND status = 'DRAFT'`,
        [
          versionId, quest.title, quest.summary, objectivesJson, quest.ageMin, quest.ageMax,
          quest.difficulty, quest.durationMin, seoJson, quest.internalName, quest.description, skillTags,
        ],
      );
    }

    const puzzles = buildQuestPuzzles(quest);
    for (const [levelIndex, level] of quest.levels.entries()) {
      const levelResult = await client.query<{ id: string }>(
        `INSERT INTO levels (id, quest_version_id, order_no, title, intro)
         VALUES ($1, $2, $3, $4, $5)
         ON CONFLICT (quest_version_id, order_no) DO UPDATE SET
           title = EXCLUDED.title, intro = EXCLUDED.intro
         RETURNING id`,
        [randomUUID(), versionId, levelIndex + 1, level.title, level.intro],
      );
      const levelId = levelResult.rows[0].id;
      for (const puzzle of puzzles.filter((item) => item.orderNo >= levelIndex * 3 + 1 && item.orderNo <= (levelIndex + 1) * 3)) {
        await client.query(
          `INSERT INTO puzzles
           (id, level_id, order_no, type, schema_version, public_payload,
            solution_private, max_attempts, max_score)
           VALUES ($1, $2, $3, $4, 1, $5::jsonb, $6::jsonb, 3, 10)
           ON CONFLICT (level_id, order_no) DO UPDATE SET
             type = EXCLUDED.type,
             public_payload = EXCLUDED.public_payload,
             solution_private = EXCLUDED.solution_private,
             max_attempts = EXCLUDED.max_attempts,
             max_score = EXCLUDED.max_score
           RETURNING id`,
          [
            randomUUID(), levelId, puzzle.orderNo, puzzle.type,
            JSON.stringify(puzzle.publicPayload), JSON.stringify(puzzle.solutionPrivate),
          ],
        ).then(async (puzzleResult) => {
          const puzzleId = puzzleResult.rows[0].id;
          await client.query(
            `INSERT INTO hints (id, puzzle_id, order_no, body)
             VALUES ($1, $2, 1, $3)
             ON CONFLICT (puzzle_id, order_no) DO UPDATE SET body = EXCLUDED.body`,
            [randomUUID(), puzzleId, puzzle.hint],
          );
        });
      }
    }

    await client.query(
      `UPDATE quest_versions SET status = 'PUBLISHED', published_at = COALESCE(published_at, NOW())
       WHERE id = $1 AND status = 'DRAFT'`,
      [versionId],
    );
    await client.query(
      `UPDATE quests SET status = 'PUBLISHED', updated_at = NOW() WHERE id = $1`,
      [questId],
    );
  }

  process.stdout.write(
    'Learning library seeded: ' + categorySeeds.length + ' categories, '
    + skillSeeds.length + ' skills and ' + questSeeds.length + ' quests ('
    + questSeeds.reduce((count, quest) => count + buildQuestPuzzles(quest).length, 0)
    + ' puzzles).\n',
  );
}
